#!/usr/bin/env bash
# =============================================================================
# scripts/sync_results_from_hpc3.sh
# =============================================================================
#
# One-way pull of experiment results from HPC3 to laptop.
#
# This script ONLY copies files from HPC3 → laptop.  It never uploads,
# and by default it never deletes laptop files (laptop-only results
# are preserved untouched).  See ``--delete`` below for the opt-in
# mirroring mode.
#
# Assumes you have ``ssh hpc3`` working via ~/.ssh/config + key auth.
#
# Generated by Stage 13.  Not regenerated by anything — edit in place.
# =============================================================================
set -euo pipefail

# ─── Defaults ────────────────────────────────────────────────────────────────
HPC3_HOST="${HPC3_HOST:-hpc3}"                         # ssh alias from ~/.ssh/config
HPC3_REPO="${HPC3_REPO:-/pub/mzafarid/CORDIS}"        # remote repo root
LOCAL_RESULTS_ROOT="${LOCAL_RESULTS_ROOT:-results}"   # local repo's results/ dir

# ─── Argument parsing ────────────────────────────────────────────────────────
EXPERIMENT=""
DRY_RUN=0
DELETE=0
QUIET=0

usage() {
    cat <<EOF
NAME
    sync_results_from_hpc3.sh — pull experiment results from HPC3 to laptop

SYNOPSIS
    bash $0 [OPTIONS] [EXPERIMENT]

DESCRIPTION
    One-way sync from HPC3 to your laptop.  Files are pulled additively
    — laptop-only result directories are NEVER touched unless --delete
    is given.  Never uploads anything.

ARGUMENTS
    EXPERIMENT
        Optional.  Name of a single experiment directory under
        results/, e.g. 'exp_sinr_cdf'.  When omitted, syncs the
        entire results/ tree (all experiments).

OPTIONS
    -n, --dry-run
        Show what would transfer, but do not actually transfer.
        Useful for sanity-checking before a large pull.

    --delete
        Mirror deletions from HPC3 — laptop files that don't exist on
        HPC3 will be REMOVED.  Use only when you want the local
        results/ tree to exactly match the cluster's.  WARNING: this
        will delete laptop-only experiment runs.

    -q, --quiet
        Suppress per-file progress; just print the summary.

    -h, --help
        Show this help message and exit.

ENVIRONMENT
    HPC3_HOST
        SSH host alias to use.  Default: 'hpc3'.  Override if your
        SSH config uses a different name or you want to connect via
        the full hostname.

    HPC3_REPO
        Absolute path to the CORDIS repo on the cluster.
        Default: '/pub/mzafarid/CORDIS'.  Override for collaborators
        with different layouts.

    LOCAL_RESULTS_ROOT
        Local results directory.  Default: 'results'.  Override only
        if you've reorganised the laptop-side layout.

EXAMPLES
    # Preview every change before pulling anything:
    bash $0 --dry-run

    # Pull every experiment's results:
    bash $0

    # Pull just one experiment:
    bash $0 exp_sinr_cdf

    # Preview before pulling sinr_cdf only:
    bash $0 --dry-run exp_sinr_cdf

    # Pull only one array's tasks + aggregated result (Stage 21):
    bash $0 --array-id 12345 exp_sinr_cdf

    # Pull as another user (collaborator on the same cluster):
    HPC3_REPO=/pub/alice/CORDIS bash $0 exp_sinr_cdf

    # Mirror the cluster exactly (DESTRUCTIVE — removes laptop-only runs):
    bash $0 --delete --dry-run     # preview first!
    bash $0 --delete                # only if dry-run looked right
EOF
}

# Stage 21: optional filter on array job ID.  When set, the sync
# pulls only the matching per-task + aggregated subdirs under the
# given experiment (requires EXPERIMENT to also be set).
ARRAY_ID=""

while [[ $# -gt 0 ]]; do
    case "$1" in
        -h|--help)
            usage
            exit 0
            ;;
        -n|--dry-run)
            DRY_RUN=1
            shift
            ;;
        --delete)
            DELETE=1
            shift
            ;;
        -q|--quiet)
            QUIET=1
            shift
            ;;
        --array-id)
            if [[ $# -lt 2 ]]; then
                echo "ERROR: --array-id requires a value" >&2; exit 2
            fi
            ARRAY_ID="$2"
            # Strip optional 'array_' prefix for user convenience.
            ARRAY_ID="${ARRAY_ID#array_}"
            shift 2
            ;;
        --array-id=*)
            ARRAY_ID="${1#--array-id=}"
            ARRAY_ID="${ARRAY_ID#array_}"
            shift
            ;;
        --)
            shift
            EXPERIMENT="${1:-}"
            break
            ;;
        -*)
            echo "ERROR: unknown option: $1" >&2
            echo "Try 'bash $0 --help' for usage." >&2
            exit 2
            ;;
        *)
            if [[ -n "$EXPERIMENT" ]]; then
                echo "ERROR: only one EXPERIMENT argument accepted (got both" \
                     "'$EXPERIMENT' and '$1')" >&2
                exit 2
            fi
            EXPERIMENT="$1"
            shift
            ;;
    esac
done

# ─── Resolve source + destination paths ──────────────────────────────────────
# Trailing slashes matter: rsync interprets "src/" as "contents of src"
# (rather than "the directory src itself").  We always want the contents
# to land inside the matching local dir.

# --array-id requires --experiment scoping (otherwise we'd have to glob
# across every exp_*/ tree and rsync doesn't natively support that with
# remote sources).
if [[ -n "$ARRAY_ID" && -z "$EXPERIMENT" ]]; then
    echo "ERROR: --array-id requires an EXPERIMENT argument (e.g. 'exp_sinr_cdf')." \
         "Without the experiment, there's no scope to filter." >&2
    exit 2
fi

if [[ -n "$EXPERIMENT" ]]; then
    # Single-experiment mode.  Light sanity check — most real
    # experiments start with 'exp_' but don't be too strict.
    if [[ "$EXPERIMENT" == */* ]]; then
        echo "ERROR: EXPERIMENT must be a plain directory name, not a path" \
             "(got '$EXPERIMENT')" >&2
        exit 2
    fi
    REMOTE="${HPC3_HOST}:${HPC3_REPO}/results/${EXPERIMENT}/"
    LOCAL="${LOCAL_RESULTS_ROOT}/${EXPERIMENT}/"
else
    REMOTE="${HPC3_HOST}:${HPC3_REPO}/results/"
    LOCAL="${LOCAL_RESULTS_ROOT}/"
fi

# ─── Build rsync flags ───────────────────────────────────────────────────────
RSYNC_FLAGS=(-avzh)              # archive + verbose + compress + human-readable
[[ $QUIET   -eq 0 ]] && RSYNC_FLAGS+=(--progress)
[[ $DRY_RUN -eq 1 ]] && RSYNC_FLAGS+=(--dry-run)
[[ $DELETE  -eq 1 ]] && RSYNC_FLAGS+=(--delete)

# Stage 21: when --array-id is set, restrict rsync to subdirs whose
# names start with array_<id>_ (matches both task_* and _aggregated).
# Anything else under the experiment dir is excluded.  Note: rsync
# applies --include/--exclude rules in order, and the final --exclude='*'
# blocks everything not explicitly included.
if [[ -n "$ARRAY_ID" ]]; then
    RSYNC_FLAGS+=(
        --include="/array_${ARRAY_ID}_task_*/"
        --include="/array_${ARRAY_ID}_task_*/**"
        --include="/array_${ARRAY_ID}_aggregated/"
        --include="/array_${ARRAY_ID}_aggregated/**"
        --exclude='/*'
    )
fi

# ─── Pre-flight ──────────────────────────────────────────────────────────────
mkdir -p "$LOCAL"

echo "─────────────────────────────────────────────────────────────────"
echo " Source:      $REMOTE"
echo " Destination: $LOCAL"
[[ -n "$ARRAY_ID" ]] && echo " Array filter: array_${ARRAY_ID}_* only"
echo " Flags:       ${RSYNC_FLAGS[*]}"
if [[ $DRY_RUN -eq 1 ]]; then
    echo " Mode:        DRY-RUN (no files transferred)"
fi
if [[ $DELETE -eq 1 ]]; then
    echo " ⚠  --delete is ON: laptop files missing from cluster WILL BE REMOVED"
fi
echo "─────────────────────────────────────────────────────────────────"

# ─── Run rsync ───────────────────────────────────────────────────────────────
rsync "${RSYNC_FLAGS[@]}" "$REMOTE" "$LOCAL"

echo "─────────────────────────────────────────────────────────────────"
if [[ $DRY_RUN -eq 1 ]]; then
    echo " Dry-run complete.  Re-run without --dry-run to apply."
else
    echo " Sync complete."
fi
echo "─────────────────────────────────────────────────────────────────"

